import { Pool } from "pg";

export interface PipelineRun {
  id: number;
  repoId: number;
  branch: string;
  commitSha: string;
  status: "queued" | "running" | "passed" | "failed";
  startedAt: Date;
}

export interface JobRow {
  id: number;
  runId: number;
  name: string;
  status: string;
  durationMs: number | null;
}

export class RunStore {
  constructor(private readonly pool: Pool) {}

  async recentRuns(repoId: number, limit: number, beforeId?: number): Promise<PipelineRun[]> {
    const params: unknown[] = [repoId, Math.min(limit, 100)];
    let cursor = "";
    if (beforeId !== undefined) {
      params.push(beforeId);
      cursor = "AND id < $3";
    }
    const { rows } = await this.pool.query(
      `SELECT id, repo_id AS "repoId", branch, commit_sha AS "commitSha", status,
              started_at AS "startedAt"
         FROM pipeline_runs
        WHERE repo_id = $1 ${cursor}
        ORDER BY id DESC
        LIMIT $2`,
      params,
    );
    return rows;
  }

  async jobsForRuns(runIds: number[]): Promise<JobRow[]> {
    if (runIds.length === 0) return [];
    const { rows } = await this.pool.query(
      `SELECT id, run_id AS "runId", name, status, duration_ms AS "durationMs"
         FROM pipeline_jobs
        WHERE run_id = ANY($1::bigint[])
        ORDER BY run_id, id`,
      [runIds],
    );
    return rows;
  }

  async authorsForCommits(repoId: number, shas: string[]): Promise<Map<string, string>> {
    if (shas.length === 0) return new Map();
    const { rows } = await this.pool.query(
      `SELECT sha, author_login AS "login" FROM commits WHERE repo_id = $1 AND sha = ANY($2)`,
      [repoId, shas],
    );
    return new Map(rows.map((r: { sha: string; login: string }) => [r.sha, r.login]));
  }
}

import { RunStore, JobRow, PipelineRun } from "./runStore";

export interface RunSummary {
  id: number;
  branch: string;
  commitSha: string;
  author: string | null;
  status: PipelineRun["status"];
  jobs: { name: string; status: string; durationMs: number | null }[];
  slowestJob: string | null;
}

export interface RunPage {
  runs: RunSummary[];
  nextCursor: number | null;
}

export class RunHistoryHandler {
  constructor(private readonly store: RunStore) {}

  async list(repoId: number, limit: number, before?: number): Promise<RunPage> {
    const runs = await this.store.recentRuns(repoId, limit, before);
    const shas = [...new Set(runs.map((r) => r.commitSha))];

    const [authors, jobsPerRun] = await Promise.all([
      this.store.authorsForCommits(repoId, shas),
      Promise.all(runs.map((r) => this.store.jobsForRuns([r.id]))),
    ]);

    const summaries = runs.map((run, i) => this.summarize(run, jobsPerRun[i], authors));
    const last = runs[runs.length - 1];
    return {
      runs: summaries,
      nextCursor: runs.length === Math.min(limit, 100) && last ? last.id : null,
    };
  }

  private summarize(run: PipelineRun, jobs: JobRow[], authors: Map<string, string>): RunSummary {
    let slowest: JobRow | null = null;
    for (const job of jobs) {
      if (job.durationMs === null) continue;
      if (!slowest || (slowest.durationMs ?? 0) < job.durationMs) slowest = job;
    }
    return {
      id: run.id,
      branch: run.branch,
      commitSha: run.commitSha,
      author: authors.get(run.commitSha) ?? null,
      status: run.status,
      jobs: jobs.map((j) => ({ name: j.name, status: j.status, durationMs: j.durationMs })),
      slowestJob: slowest ? slowest.name : null,
    };
  }
}
